WITH parsed AS (SELECT id, plan, effective_from, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT plan, COUNT(DISTINCT id) AS distinct_ids, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count, ROUND(AVG(avg_tier_price), 2) AS avg_avg_tier_price, ROUND(SUM(avg_tier_price) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS avg_tier_price_per_basic FROM parsed GROUP BY plan;
